CREATE SCHEMA IF NOT EXISTS industrendindia AUTHORIZATION CURRENT_USER; SET search_path TO industrendindia,pg_catalog;
CREATE TABLE IF NOT EXISTS payment_attempts(payment_attempt_id uuid PRIMARY KEY,order_id uuid NOT NULL,provider varchar(40) NOT NULL,provider_payment_id varchar(160),status varchar(24) NOT NULL CHECK(status IN('CREATED','AUTHORIZED','CAPTURED','FAILED','REFUNDED')),amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency char(3) NOT NULL DEFAULT 'INR',idempotency_key varchar(100) NOT NULL UNIQUE,provider_payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE INDEX IF NOT EXISTS payment_attempts_order_idx ON payment_attempts(order_id,created_at DESC); CREATE UNIQUE INDEX IF NOT EXISTS payment_provider_id_uq ON payment_attempts(provider,provider_payment_id) WHERE provider_payment_id IS NOT NULL;
